def _anchor_row_uses(row: Dict[str, Any]) -> List[str]:
    """返回锚点行的用途列表（规范序）；无 uses 的旧记录为全用途。"""
    uses = row.get("uses")
    if uses is None:
        return list(TRUST_ANCHOR_USES)
    return list(uses)


def _anchor_use_allowed(row: Dict[str, Any], use: str) -> bool:
    """锚点行是否允许指定用途：无 uses 限制（旧记录/省略）为全用途。"""
    uses = row.get("uses")
    if uses is None:
        return True
    return use in uses


